package com.habilitesrandom;
import com.habilitesrandom.api.*;import com.habilitesrandom.content.BuiltinContent;import com.habilitesrandom.registry.*;import org.junit.jupiter.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class LaunchCharacterAuditTest {
 ContentCatalog catalog;Map<String,CharacterDefinition> byName;
 @BeforeEach void load(){catalog=new ContentCatalog();BuiltinContent.register(new DefaultContentRegistrar(catalog,"audit",1));byName=new HashMap<>();new CharacterRegistry(catalog).getAll().forEach(c->byName.put(c.displayName(),c));}
 @Test void mandatoryCharactersHaveExecutableKitsAndForms(){for(String name:List.of("Satoru Gojo","Ryomen Sukuna","Yuji Itadori","Goku","Naruto Uzumaki","Boruto Uzumaki","Sung Jin-Woo","Meliodas","Escanor","Mr. Satan","Usopp")){var c=byName.get(name);assertNotNull(c,name);assertEquals(4,c.abilityIds().size(),name);for(var id:c.abilityIds()){var a=catalog.find(ContentTypes.ABILITY,id).orElseThrow();assertTrue(a.cooldownTicks()>0);assertTrue(a.damage()>0||a.types().contains(AbilityType.DEFENSE)||a.types().contains(AbilityType.MOVEMENT));assertFalse(a.soundId().isBlank());assertFalse(a.particleId().isBlank());}var form=catalog.find(ContentTypes.TRANSFORMATION,c.transformationId()).orElseThrow();assertTrue(form.durationTicks()>0);assertTrue(form.damageMultiplier()>1);assertFalse(form.soundId().isBlank());}}
 @Test void allLaunchContentIsComplete(){CatalogValidator.validate(catalog);assertTrue(new CharacterRegistry(catalog).getAll().size()>=90);assertEquals(new CharacterRegistry(catalog).getAll().size()*4,new AbilityRegistry(catalog).getAll().size());assertEquals(new CharacterRegistry(catalog).getAll().size(),new TransformationRegistry(catalog).getAll().size());}
 @Test void signatureContentIsPresent(){assertEquals("Black Flash",catalog.find(ContentTypes.ABILITY,HabilitesRandom.id("yuji_itadori/black_flash")).orElseThrow().displayName());assertEquals("Infinity Guard",catalog.find(ContentTypes.ABILITY,HabilitesRandom.id("satoru_gojo/signature_strike")).orElseThrow().displayName());assertEquals("Ultra Instinct",catalog.find(ContentTypes.TRANSFORMATION,HabilitesRandom.id("goku/powerful_form")).orElseThrow().displayName());}
}
